"""Langfuse prompt cache with TTL and version-change detection."""from __future__ import annotationsimport loggingimport timefrom dataclasses import dataclassfrom datetime import UTC, datetimefrom typing import TYPE_CHECKINGfrom app.agent.prompt_resolver import ResolvedPrompt, resolve_promptfrom app.config import Settings, get_settingsif TYPE_CHECKING:    from app.agent.run_config import PromptSectionlogger = logging.getLogger("prompts.store")@dataclassclass _CacheEntry:    resolved: ResolvedPrompt    fetched_at: float    fetched_at_wall: datetime_cache: dict[str, _CacheEntry] = {}def reset_prompt_store() -> None:    """Clear prompt cache (tests)."""    _cache.clear()def _cache_key(prompt: PromptSection) -> str:    label = prompt.label or "production"    return f"{prompt.name}@{label}"def _format_version(version: int | None) -> str:    return f"v{version}" if version is not None else "n/a"def _version_transition(prev_version: int | None, new_version: int | None) -> str:    if prev_version is None:        return _format_version(new_version)    if new_version is None:        return f"{_format_version(prev_version)} → n/a"    if prev_version == new_version:        return f"{_format_version(new_version)} (unchanged)"    return f"{_format_version(prev_version)} → {_format_version(new_version)} (changed)"def _log_prompt_cache_event(    *,    event: str,    key: str,    prev_version: int | None,    resolved: ResolvedPrompt,    ttl: int,    cache_age_sec: int | None,    cached_since: datetime | None,) -> None:    refreshed_at = datetime.now(UTC)    details = [        f"{event} {key} — {_version_transition(prev_version, resolved.version)}",        f"source={resolved.source}",        f"ttl={ttl}s",        f"refreshed_at={refreshed_at.isoformat()}",    ]    if cache_age_sec is not None:        details.insert(2, f"cache_age={cache_age_sec}s")    if cached_since is not None:        details.append(f"cached_since={cached_since.isoformat()}")    if resolved.version_updated_at is not None:        details.append(f"langfuse_updated_at={resolved.version_updated_at.isoformat()}")    logger.info(", ".join(details))def fetch(    prompt: PromptSection,    *,    settings: Settings | None = None,) -> tuple[ResolvedPrompt, bool]:    """Return cached Langfuse prompt; refresh on TTL expiry.    Returns:        (resolved_prompt, version_changed) — version_changed is True when        Langfuse prompt version differs from the previously cached one.    """    if prompt.source != "langfuse":        cfg = settings or get_settings()        return resolve_prompt(prompt, settings=cfg), False    cfg = settings or get_settings()    ttl = max(int(cfg.prompt_cache_ttl_sec), 1)    key = _cache_key(prompt)    now = time.monotonic()    entry = _cache.get(key)    needs_refresh = entry is None or (now - entry.fetched_at) >= ttl    if not needs_refresh and entry is not None:        return entry.resolved, False    prev_version = entry.resolved.version if entry else None    cache_age_sec = int(now - entry.fetched_at) if entry is not None else None    cached_since = entry.fetched_at_wall if entry is not None else None    resolved = resolve_prompt(prompt, settings=cfg)    new_version = resolved.version    version_changed = (        prev_version is not None and new_version is not None and prev_version != new_version    )    if entry is None:        _log_prompt_cache_event(            event="CACHE MISS",            key=key,            prev_version=None,            resolved=resolved,            ttl=ttl,            cache_age_sec=None,            cached_since=None,        )    else:        _log_prompt_cache_event(            event="CACHE REFRESH",            key=key,            prev_version=prev_version,            resolved=resolved,            ttl=ttl,            cache_age_sec=cache_age_sec,            cached_since=cached_since,        )    _cache[key] = _CacheEntry(        resolved=resolved,        fetched_at=now,        fetched_at_wall=datetime.now(UTC),    )    return resolved, version_changed